package model

import (
	"os"
	"slices"
	"testing"

	"github.com/QuantumNous/new-api/common"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"gorm.io/gorm"
)

// Run against dedicated fresh/upgrade databases only. The upgrade fixture is
// generated by the actual released code before this test is invoked.
func TestReleaseDatabaseMatrix(t *testing.T) {
	dsn := os.Getenv("TEST_RELEASE_DSN")
	if dsn == "" {
		t.Skip("TEST_RELEASE_DSN is not configured")
	}
	mode := os.Getenv("TEST_RELEASE_MODE")
	require.Contains(t, []string{"fresh", "upgrade"}, mode)
	originalDB, originalLog := DB, LOG_DB
	originalMainType, originalLogType := common.MainDatabaseType(), common.LogDatabaseType()
	originalMaster, originalRedis, originalBatch := common.IsMasterNode, common.RedisEnabled, common.BatchUpdateEnabled
	originalPath, originalQuotaUnit := common.SQLitePath, common.QuotaPerUnit
	t.Cleanup(func() {
		for _, db := range []*gorm.DB{DB, LOG_DB} {
			if db != nil && db != originalDB && db != originalLog {
				sqlDB, err := db.DB()
				require.NoError(t, err)
				require.NoError(t, sqlDB.Close())
			}
		}
		DB, LOG_DB = originalDB, originalLog
		common.SetDatabaseTypes(originalMainType, originalLogType)
		common.IsMasterNode, common.RedisEnabled, common.BatchUpdateEnabled = originalMaster, originalRedis, originalBatch
		common.SQLitePath, common.QuotaPerUnit = originalPath, originalQuotaUnit
		initCol()
	})
	t.Setenv("SQL_DSN", dsn)
	t.Setenv("LOG_SQL_DSN", os.Getenv("TEST_RELEASE_LOG_DSN"))
	if path := os.Getenv("TEST_RELEASE_SQLITE_PATH"); path != "" {
		common.SQLitePath = path
	}
	common.IsMasterNode, common.RedisEnabled, common.BatchUpdateEnabled = true, false, false
	common.QuotaPerUnit = 500000
	require.NoError(t, InitDB())
	require.NoError(t, InitLogDB())
	require.NotSame(t, DB, LOG_DB, "log database must be separately configured")
	versionQuery := "select version()"
	if common.UsingMainDatabase(common.DatabaseTypeSQLite) {
		versionQuery = "select sqlite_version()"
	}
	var version string
	require.NoError(t, DB.Raw(versionQuery).Scan(&version).Error)
	t.Logf("database %s: %s; mode=%s", common.MainDatabaseType(), version, mode)
	require.True(t, DB.Migrator().HasColumn(&TopUp{}, "provider_payload"))
	before := releaseDatabaseIndexSnapshot(t, DB)
	logBefore := releaseDatabaseIndexSnapshot(t, LOG_DB)
	firstDB, firstLog := DB, LOG_DB
	require.NoError(t, InitDB())
	require.NoError(t, InitLogDB())
	for _, db := range []*gorm.DB{firstDB, firstLog} {
		sqlDB, err := db.DB()
		require.NoError(t, err)
		require.NoError(t, sqlDB.Close())
	}
	recorder := &migrationSQLRecorder{}
	DB = DB.Session(&gorm.Session{Logger: recorder})
	LOG_DB = LOG_DB.Session(&gorm.Session{Logger: recorder})
	require.NoError(t, ensureUserQuotaColumns(DB, common.MainDatabaseType()))
	require.NoError(t, migrateDB())
	require.NoError(t, migrateLOGDB())
	assert.Empty(t, recorder.schemaMutations(), "repeated startup must not issue schema DDL")
	assert.Equal(t, before, releaseDatabaseIndexSnapshot(t, DB), "repeated startup preserves indexes")
	assert.Equal(t, logBefore, releaseDatabaseIndexSnapshot(t, LOG_DB), "repeated log startup preserves indexes")

	if mode == "upgrade" {
		var user User
		require.NoError(t, DB.Where("username = ?", "release_fixture_user").First(&user).Error)
		assert.Equal(t, 1234567, user.Quota)
		assert.Equal(t, "fixture@example.invalid", user.Email)
		var token Token
		require.NoError(t, DB.Where(commonKeyCol+" = ?", "release_fixture_token").First(&token).Error)
		assert.Equal(t, 345678, token.RemainQuota)
		var group PrefillGroup
		require.NoError(t, DB.Where("name = ?", "release_fixture_group").First(&group).Error)
		assert.JSONEq(t, `["fixture-model"]`, string(group.Items))
		var option Option
		require.NoError(t, DB.Where(commonKeyCol+" = ?", "ReleaseFixture").First(&option).Error)
		assert.Equal(t, "preserved", option.Value)
		var log Log
		require.NoError(t, LOG_DB.Where("user_id = ? AND quota = ?", user.Id, 45678).First(&log).Error)
		assert.Equal(t, 123, log.PromptTokens)
		oldOrder := GetTopUpByTradeNo("release_fixture_order")
		require.NotNil(t, oldOrder)
		assert.Empty(t, oldOrder.ProviderPayload)
		already, err := RechargeIPayNow(oldOrder.TradeNo, "127.0.0.1")
		require.NoError(t, err)
		assert.False(t, already)
		already, err = RechargeIPayNow(oldOrder.TradeNo, "127.0.0.1")
		require.NoError(t, err)
		assert.True(t, already)
		require.NoError(t, DB.First(&user, user.Id).Error)
		assert.Equal(t, 2234567, user.Quota, "legacy NULL payload retains amount-based credit")
		duplicateToken := Token{UserId: user.Id, Key: token.Key}
		assert.Error(t, DB.Create(&duplicateToken).Error, "token uniqueness survives upgrade")
		assert.Error(t, DB.Create(&PrefillGroup{Name: group.Name, Type: group.Type}).Error, "prefill uniqueness survives upgrade")
	}

	user := User{Username: "snapshot_" + common.GetUUID(), AffCode: common.GetRandomString(4), Group: "default", Quota: 1000}
	require.NoError(t, DB.Create(&user).Error)
	grant := BonusQuotaGrant{UserId: user.Id, Source: BonusQuotaSourceCheckin, SourceRef: common.GetUUID(), AmountTotal: 500, AmountRemaining: 500, Status: BonusQuotaStatusActive}
	require.NoError(t, DB.Create(&grant).Error)
	order := TopUp{UserId: user.Id, Amount: 1, Money: .75, TradeNo: common.GetUUID(), PaymentMethod: PaymentMethodIPayNow, PaymentProvider: PaymentProviderIPayNow, Status: common.TopUpStatusPending}
	require.NoError(t, order.SetIPayNowQuota(750000))
	require.NoError(t, order.Insert())
	duplicate := order
	duplicate.Id = 0
	assert.Error(t, DB.Create(&duplicate).Error, "order uniqueness survives migration")
	common.QuotaPerUnit = 1000000
	already, err := RechargeIPayNow(order.TradeNo, "127.0.0.1")
	require.NoError(t, err)
	assert.False(t, already)
	already, err = RechargeIPayNow(order.TradeNo, "127.0.0.1")
	require.NoError(t, err)
	assert.True(t, already)
	require.NoError(t, ManualCompleteTopUp(order.TradeNo, "127.0.0.1"))
	require.NoError(t, DB.First(&user, user.Id).Error)
	assert.Equal(t, 751000, user.Quota, "snapshot is credited once independent of current pricing")
	require.NoError(t, DB.First(&grant, grant.Id).Error)
	assert.Equal(t, 500, grant.AmountRemaining, "cash top-up must not alter reward balance")
	var logs []Log
	require.NoError(t, LOG_DB.Where("user_id = ? AND type = ?", user.Id, LogTypeTopup).Find(&logs).Error)
	require.Len(t, logs, 1)
	assert.Equal(t, 750000, logs[0].Quota)
	var mainLogCount int64
	require.NoError(t, DB.Model(&Log{}).Where("user_id = ? AND type = ?", user.Id, LogTypeTopup).Count(&mainLogCount).Error)
	assert.Zero(t, mainLogCount, "top-up log belongs only in the separately configured log database")
	loaded := GetTopUpByTradeNo(order.TradeNo)
	require.NotNil(t, loaded)
	credited, err := loaded.IPayNowQuotaSnapshot()
	require.NoError(t, err)
	assert.Equal(t, 750000, credited)
	encoded, err := common.Marshal(loaded)
	require.NoError(t, err)
	assert.NotContains(t, string(encoded), "provider_payload")

	bad := TopUp{UserId: user.Id, Amount: 1, TradeNo: common.GetUUID(), PaymentMethod: PaymentMethodIPayNow, PaymentProvider: PaymentProviderIPayNow, Status: common.TopUpStatusPending, ProviderPayload: `{"version":2,"credited_quota":750000}`}
	require.NoError(t, bad.Insert())
	_, err = RechargeIPayNow(bad.TradeNo, "127.0.0.1")
	require.ErrorIs(t, err, ErrInvalidTopUpQuota)
	assert.Equal(t, common.TopUpStatusPending, GetTopUpByTradeNo(bad.TradeNo).Status)

	reserved, err := TryReserveUserQuota(user.Id, 123)
	require.NoError(t, err)
	assert.True(t, reserved)
	require.NoError(t, DB.First(&user, user.Id).Error)
	assert.Equal(t, 750877, user.Quota, "synchronous reservation must be durable before return")
	require.NoError(t, IncreaseUserQuota(user.Id, 123, false))
	require.NoError(t, DB.First(&user, user.Id).Error)
	assert.Equal(t, 751000, user.Quota, "synchronous refund must be durable before return")
	reserved, err = TryReserveUserQuota(user.Id, 751001)
	require.NoError(t, err)
	assert.False(t, reserved)

	require.NoError(t, LOG_DB.Create(&Log{UserId: user.Id, Username: user.Username, Type: LogTypeConsume, Quota: 12345, CreatedAt: common.GetTimestamp(), PromptTokens: 80, CompletionTokens: 20}).Error)
	stat, err := SumUsedQuota(LogTypeConsume, 0, 0, "", user.Username, "", 0, "")
	require.NoError(t, err)
	assert.Equal(t, 12345, stat.Quota, "usage must not be overwritten by RPM/TPM scanning")
	assert.Equal(t, 1, stat.Rpm)
	assert.Equal(t, 100, stat.Tpm)

	plan := SubscriptionPlan{Title: "Database matrix balance purchase", PriceAmount: .1, Enabled: true, DurationUnit: SubscriptionDurationMonth, DurationValue: 1, TotalAmount: 100, MaxPurchasePerUser: 1, UpgradeGroup: "pro"}
	require.NoError(t, DB.Create(&plan).Error)
	InvalidateSubscriptionPlanCache(plan.Id)
	t.Cleanup(func() { InvalidateSubscriptionPlanCache(plan.Id) })
	sqlDB, err := DB.DB()
	require.NoError(t, err)
	sqlDB.SetMaxOpenConns(1)
	require.NoError(t, PurchaseSubscriptionWithBalance(user.Id, plan.Id), "transaction must not request a second database connection")
	require.NoError(t, DB.First(&user, user.Id).Error)
	assert.Equal(t, 651000, user.Quota)
	assert.Equal(t, "pro", user.Group)
	var subscription UserSubscription
	require.NoError(t, DB.Where("user_id = ? AND plan_id = ?", user.Id, plan.Id).First(&subscription).Error)
	assert.Equal(t, PaymentMethodBalance, subscription.Source)
	assert.Equal(t, "default", subscription.PrevUserGroup)
	var purchase SubscriptionOrder
	require.NoError(t, DB.Where("user_id = ? AND plan_id = ?", user.Id, plan.Id).First(&purchase).Error)
	assert.Equal(t, PaymentProviderBalance, purchase.PaymentProvider)
	assert.Equal(t, "charged_quota=100000", purchase.ProviderPayload)
	assert.Equal(t, common.TopUpStatusSuccess, purchase.Status)
	require.Error(t, PurchaseSubscriptionWithBalance(user.Id, plan.Id), "purchase limit must roll back its balance reservation")
	require.NoError(t, DB.First(&user, user.Id).Error)
	assert.Equal(t, 651000, user.Quota)
	var subscriptionCount, orderCount int64
	require.NoError(t, DB.Model(&UserSubscription{}).Where("user_id = ? AND plan_id = ?", user.Id, plan.Id).Count(&subscriptionCount).Error)
	require.NoError(t, DB.Model(&SubscriptionOrder{}).Where("user_id = ? AND plan_id = ?", user.Id, plan.Id).Count(&orderCount).Error)
	assert.EqualValues(t, 1, subscriptionCount)
	assert.EqualValues(t, 1, orderCount)
}

func releaseDatabaseIndexSnapshot(t *testing.T, db *gorm.DB) map[string][]string {
	t.Helper()
	tables, err := db.Migrator().GetTables()
	require.NoError(t, err)
	result := make(map[string][]string, len(tables))
	for _, table := range tables {
		indexes, err := db.Migrator().GetIndexes(table)
		require.NoError(t, err)
		for _, index := range indexes {
			unique, _ := index.Unique()
			primary, _ := index.PrimaryKey()
			value, err := common.Marshal([]any{index.Name(), index.Columns(), unique, primary})
			require.NoError(t, err)
			result[table] = append(result[table], string(value))
		}
		slices.Sort(result[table])
	}
	return result
}
